		public void CMD_ForceQuitPokeSelect() {
            ForceQuitMenuUI<PokemonBattleWindow>(window =>
            {
                var viewSystem = BattleViewCore.Instance.ViewSystem;
                var party = viewSystem.GetBattleParty_Self();
                byte count = party.GetMemberCount();
                var pokemonParams = new List<BTL_POKEPARAM>();
                for (byte i = 0; i < count; i++)
                {
                    var bpp = party.GetMemberData(i);
                    if (bpp.IsFightEnable() && viewSystem.PokeIDToViewPos(bpp.GetID()) == BtlvPos.BTL_VPOS_ERROR)
                    {
                        pokemonParams.Add(bpp);
                        break;
                    }
                }

                // posType is never read by OnSwapPokemon (the binary leaves w2 unset at 01e7d158)
                OnSwapPokemon(pokemonParams, PokemonBattleWindow.PositionType.None);
                window.Close(window.onClosed, UIWindow.WINDOWID_FIELD);
            }, false);
        }
		public bool CMD_WaitForceQuitPokeSelect() {
            return _isMenuUIEnd;
        }
