		public void CMD_StartMsg(global::Dpr.Battle.Logic.BTLV_STRPARAM param, bool isKeyWait = false) {
            bool keyWait;
            switch (param.strID)
            {
                case (ushort)BTL_STRID_STD.IrekaeConfirm:
                    _isMessageSleep = true;
                    keyWait = param.wait == 0;
                    break;
                case (ushort)BTL_STRID_STD.LoseStart:
                case (ushort)BTL_STRID_STD.GetMoney:
                    keyWait = param.wait == 0;
                    break;
                default:
                    // (01e776bc tests SelectAction / SelectRotation (0x52/0x53) but the result is dead - they take this path too)
                    keyWait = param.wait == 0 && isKeyWait;
                    break;
            }

            SetMessageQueue(BtlvUtility.BTLV_STRPARAM_to_StrBuf(param), new MsgShowParam(keyWait, param.wait == 0 ? 12 : param.wait));
        }
