            var trainerID = viewSystem.GetMainModule().GetClientTrainerID(clientID);
            viewSystem.GetMainModule().GetClientTrainerMsg(clientID, (TrainerMessageID)param, out string messageLabel, out string sequenceName);
            if (string.IsNullOrEmpty(messageLabel))
