		public void Startup() {
            _actionList.Startup();
            _wazaList.Startup();
            _pokeBallList.Startup();
            _wazaDescription.Startup();
            foreach (var statusWindow in _statusWindows)
            {
                if (statusWindow == null)
                    continue;

                statusWindow.Startup();
            }

            _tokuseiNear.Startup();
            _tokuseiFar.Startup();
            _ballPlateNear.Startup();
            _ballPlateFar.Startup();
            _safariBall.Startup();
            _targetSelect.Startup();
            _commTime.Startup();
            _cursor.SetActive(false);
            _selectItem = ItemNo.DUMMY_DATA;
            _selectWaza = -1;
            _decoImage.enabled = false;
            _decoImage.transform.localPosition = new Vector3(DECO_HIDE_POS_X, DECO_POS_Y, 0.0f);
            _decoImage.transform.rotation = Quaternion.Euler(0.0f, 0.0f, DECO_HIDE_ROT);
            UIManager.onUseItemInBattle = (id, wazaIndex, info) =>
            {
                if (_uiWindow is UIBag)
                {
                    _selectPoke = id;
                    _selectItem = (ItemNo)info.Id;
                    _selectWaza = wazaIndex;
                    return;
                }

                if (_uiWindow is PokemonBattleWindow)
                {
                    var party = _pokeSelParam.GetParty();
                    for (byte i = 0; i < party.GetMemberCount(); i++)
                    {
                        if (id == party.GetMemberData(i).GetID())
                        {
                            byte clientID = BattleViewCore.Instance.ViewSystem.GetClientID();
                            _pokeSelResult.SetItemUse((BTL_CLIENT_ID)clientID, i, (ushort)info.Id, (byte)wazaIndex);
                            return;
                        }
                    }
                }
            };
        }
		public void OnUpdate(float deltaTime) {
            _isMessageOpen = IsOpenMessage();
            if (_autoPilot == null || _autoPilot.State != BUIAutoPilot.AutoPilotState.Running)
            {
                _actionList.OnUpdate(deltaTime);
                _wazaList.OnUpdate(deltaTime);
                _pokeBallList.OnUpdate(deltaTime);
                _targetSelect.OnUpdate(deltaTime);
                _commTime.OnUpdate(deltaTime);
                if (_autoPilot != null && _autoPilot.State == BUIAutoPilot.AutoPilotState.Done)
                    _autoPilot = null;
            }

            if (IsDebugHide)
            {
                if (_uiCanvasGroup == null)
                {
                    _uiCanvasGroup = gameObject.AddComponent<CanvasGroup>();
                    if (_uiCanvasGroup == null)
                        return;
                }

                if (_uiCanvasGroup.alpha != 0.0f)
                    _uiCanvasGroup.alpha = 0.0f;

                if (MsgWindow.MsgWindowManager.Instance.MsgWindow.isActiveAndEnabled)
                    MsgWindow.MsgWindowManager.Instance.MsgWindow.SetActive(false);
            }
            else if (_uiCanvasGroup != null && _uiCanvasGroup.alpha == 0.0f)
            {
                _uiCanvasGroup.alpha = 1.0f;
            }
        }
