		public void OnHUDEvent(global::Dpr.Battle.View.Systems.HUDEventID eventId, global::Dpr.Battle.View.Systems.BattleViewSystem pViewSystem) {
            DispInfo dispInfo = null;
            switch (eventId)
            {
                case HUDEventID.kInitial:
                    _isFirstTime = true;
                    InitStatusWindows(true);
                    _ballPlateNear.Initialize(BattleViewSystem.BattleViewSide.PLAYER_SIDE, _ballLargeSprites);
                    _ballPlateFar.Initialize(BattleViewSystem.BattleViewSide.ENEMY_SIDE, _ballLargeSprites);
                    break;

                case HUDEventID.kStartWaitCamera:
                    if (_isFirstTime)
                    {
                        if (pViewSystem.GetBtlvMode() == BattleViewBase.BtlvMode.CAPTURE)
                            BeginTutorialCapture();

                        _isFirstTime = false;
                    }
                    break;

                case HUDEventID.kCommandInputEnd:
                    SwitchShowStatusWindows(false);
                    SwitchShowDecoImage(false);
                    _swapWaitPokemon = null;
                    _currentPoke = null;
                    break;

                case HUDEventID.kEndWaitCamera:
                    if (_coCloseMenuUI != null)
                    {
                        StopCoroutine(_coCloseMenuUI);
                        _coCloseMenuUI = null;
                    }
                    break;

                case HUDEventID.kDamageEffectEnd:
                    if (preHUDEventId != HUDEventID.kDamageEffectEnd || IsOpenedStatus())
                        dispInfo = new DispInfo();
                    break;

                case HUDEventID.kDeadActStart:
                case HUDEventID.kYesNo:
                    // Apply never reads interpFrame (the binary leaves w1 = eventId @01e757a8)
                    Apply(0);
                    dispInfo = new DispInfo();
                    break;

                case HUDEventID.kMemberOutStart:
                case HUDEventID.kBallThrow:
                case HUDEventID.kTrainerInLose:
                    dispInfo = new DispInfo();
                    break;

                case HUDEventID.kMemberChangeStart:
                    InitStatusWindows(true);
                    dispInfo = new DispInfo();
                    break;

                case HUDEventID.kSimpleHPEffectStart:
                case HUDEventID.kSickIcon:
                    Apply(0);
                    break;

                case HUDEventID.kPokeChangeEnd:
                    InitStatusWindows(false);
                    break;

                case HUDEventID.kMoveMember:
                    InitStatusWindows(true);
                    break;
            }

            if (dispInfo != null)
                SwitchShowStatusWindows(dispInfo.isPlayerPlateVisible);

            preHUDEventId = eventId;
        }
		public void Apply(int interpFrame) {
            var viewSystem = BattleViewCore.Instance.ViewSystem;
            for (int i = 0; i < _statusWindows.Length; i++)
            {
                var bpp = new BTL_POKEPARAM();
                if (viewSystem.GetBattlePokeParam_forUI(bpp, (BtlvPos)i))
                {
                    var party = viewSystem.GetBattleParty(viewSystem.GetBtlvPosToClientId((BtlvPos)i));
                    _statusWindows[i].Apply(party, bpp, false, false);
                }
            }

            if (viewSystem.GetBattleRule() == BtlRule.BTL_RULE_SAFARI)
                _safariBall.SetBallCount(viewSystem.GetSafariBallNum());
        }
