            {
                var bpp = new BTL_POKEPARAM();
                if (!viewSystem.GetBattlePokeParam_forUI(bpp, (BtlvPos)i))
                    continue;

                bool isUpPosition = rule != BtlRule.BTL_RULE_SINGLE && rule != BtlRule.BTL_RULE_SAFARI && _currentPoke != null && bpp.GetID() == _currentPoke.GetID();
                _statusWindows[i].SetCurrentPokemonStatus(isUpPosition);
            }
