		private void InitStatusWindows(bool isEnableTokusei) {
            var viewSystem = BattleViewCore.Instance.ViewSystem;
            for (int i = 0; i < 5; i++)
            {
                if (viewSystem.GetViewSrcData((BtlvPos)i) != null)
                    InitializeStatusWindow((BtlvPos)i, isEnableTokusei);
                else if (i < _statusWindows.Length)
                    _statusWindows[i].Initialize((BtlvPos)i, null, 0, null, null, true);
            }
        }
		private void InitializeStatusWindow(global::Dpr.Battle.Logic.BtlvPos pos, bool isEnableTokusei) {
            var viewSystem = BattleViewCore.Instance.ViewSystem;
            var bpp = new BTL_POKEPARAM();
            if (!viewSystem.GetBattlePokeParam_forUI(bpp, pos))
            {
                _statusWindows[(int)pos].Initialize(pos, null, 0, null, null, true);
                return;
            }

            var competitor = viewSystem.GetMainModule().GetCompetitor(true);
            byte clientID = viewSystem.GetBtlvPosToClientId(pos);
            var party = viewSystem.GetBattleParty(clientID);
            _statusWindows[(int)pos].Initialize(pos, bpp, clientID, party, _ballSprites, competitor != BtlCompetitor.BTL_COMPETITOR_WILD);
            var side = pos.GetBattleSide();
            if (isEnableTokusei)
                (side == BattleViewSystem.BattleViewSide.PLAYER_SIDE ? _tokuseiNear : _tokuseiFar).Initialize(bpp, true);
        }
