		private global::System.Collections.IEnumerator SwitchShowStatusWindowCoroutine(global::Dpr.Battle.Logic.BtlvPos vPos, bool isShow) {
            BUIStatusWindow window = GetStatusWindow(vPos);
            if (vPos == BtlvPos.BTL_VPOS_FAR_1 || vPos == BtlvPos.BTL_VPOS_FAR_2)
            {
                while (IsOpenMessage() || window.IsTransition)
                {
                    if (isShow && !window.isReservationOpen)
                        window.isReservationOpen = true;

                    yield return null;
                }
            }
            else
            {
                while (IsOpenMessage() || window.IsTransition)
                {
                    if (isShow && !window.isReservationOpen)
                        window.isReservationOpen = true;

                    yield return null;
                }
            }

            if (isShow)
            {
                if (!window.DoDisplay)
                    yield break;

                window.isReservationOpen = false;
                window.ShowBallBar(true);
                window.Show(null);
            }
            else if (window.IsShow)
            {
                StartCoroutine(CloseStatusWindow(window));
            }
        }
