		private global::System.Collections.IEnumerator SwitchShowStatusWindowsCoroutine(bool isShow) {
            while (IsOpenMessage() || IsStatusWindowTarasit())
                yield return null;

            SwitchShowStatusWindowsCore(isShow, true);
        }
		private void SwitchShowStatusWindowsCore(bool isShow, bool isForceBallHide = true) {
            var rule = BattleViewCore.Instance.ViewSystem.GetBattleRule();
            for (int i = 0; i < _statusWindows.Length; i++)
            {
                var window = _statusWindows[i];
                if (window == null)
                    continue;

                if (rule == BtlRule.BTL_RULE_SAFARI && i == 0)
                {
                    if (isShow)
                        _safariBall.Show(null);
                    else
                        _safariBall.Hide(false, null);

                    continue;
                }

                if (isShow)
                {
                    if (!window.DoDisplay)
                        continue;

                    window.isReservationOpen = false;
                    window.ShowBallBar(isForceBallHide);
                    if (!window.isOpenState)
                        window.Show(null);
                }
                else
                {
                    if (!window.IsShow || window.isCloseState)
                        continue;

                    StartCoroutine(CloseStatusWindow(window));
                }
            }
        }
		public bool IsOpenedStatus() {
            for (int i = 0; i < _statusWindows.Length; i++)
            {
                if (_statusWindows[i].isInitialized && _statusWindows[i].DoDisplay && _statusWindows[i].isCloseState)
                    return false;
            }

            return true;
        }
