            for (int i = 0; i < _statusWindows.Length; i++)
            {
                if (_statusWindows[i].isInitialized && _statusWindows[i].DoDisplay && _statusWindows[i].isOpenState)
                    return false;
            }

            return true;
        }
		public bool IsSeqEndWait() {
            if (SeqEndWaitSafetyCount < SEQ_END_WAIT_SAFETY_COUNT)
            {
                if (!IsEndMessage())
                {
#if PC_UNLOCKED_FPS
                    SeqEndWaitSafetyCount += PcPlatform.PcFrameClock.Ticks;
#else
                    SeqEndWaitSafetyCount++;
#endif
                    return true;
                }

                for (int i = 0; i < _statusWindows.Length; i++)
                {
                    var window = _statusWindows[i];
                    if (window.isInitialized && window.DoDisplay &&
                        (window.isReservationOpen || window.animationState == BattleViewUICanvasBase.BattleUIAnimationState.Opening || window.IsHpBarPlaying))
                    {
#if PC_UNLOCKED_FPS
                        SeqEndWaitSafetyCount += PcPlatform.PcFrameClock.Ticks;
#else
                        SeqEndWaitSafetyCount++;
#endif
                        return true;
                    }
                }
            }

            SeqEndWaitSafetyCount = 0;
            return false;
        }
		private global::System.Collections.IEnumerator CloseStatusWindow(global::Dpr.Battle.View.UI.BUIStatusWindow window) {
            while (window.IsHpBarPlaying)
                yield return null;

            window.SetCurrentPokemonStatus(false);
            window.Hide(false, null);
        }
		private bool IsShowStatusEnemyOnly(global::System.Collections.Generic.List<bool> flags) {
            if (flags.IsNullOrEmpty() || flags.Count != 4)
                return false;

            return !flags[0] && !flags[2] && (flags[1] || flags[3]);
        }
		private bool IsStatusWindowTarasit() {
            for (int i = 0; i < _statusWindows.Length; i++)
            {
                if (_statusWindows[i].IsTransition)
                    return true;
            }

            return false;
        }
		public bool Wait() {
            foreach (var window in _statusWindows)
            {
                if (window == null)
                    continue;

                if (window.animationState == BattleViewUICanvasBase.BattleUIAnimationState.Opening)
                    return false;

                if (!window.IsShow)
                    continue;

                if (window.IsHpBarPlaying)
                    return false;

                if (window.animationState != BattleViewUICanvasBase.BattleUIAnimationState.Opened)
                    continue;

#if PC_UNLOCKED_FPS
                if (seqDotDispWaitTime < SEQ_END_WAIT_DOT_DIST_MAX || PcPlatform.PcFrameClock.Ticks == 0)
#else
                if (seqDotDispWaitTime < SEQ_END_WAIT_DOT_DIST_MAX)
#endif
                {
#if PC_UNLOCKED_FPS
                    seqDotDispWaitTime += PcPlatform.PcFrameClock.Ticks;
#else
                    seqDotDispWaitTime++;
#endif
                    return false;
                }

                seqDotDispWaitTime = 0;
                return true;
            }

            return true;
        }
