		private void SwitchShowDecoImage(bool isShow) {
            Action callback = null;
            if (_isShowDeco == isShow)
                return;

            _isShowDeco = isShow;
            bool isEnabled = _decoImage.enabled;
            float posX;
            float rot;
            if (isShow)
            {
                if (isEnabled && _decoballSequence == null)
                    return;

                _decoImage.transform.localPosition = new Vector3(DECO_HIDE_POS_X, DECO_POS_Y, 0.0f);
                _decoImage.transform.rotation = Quaternion.Euler(0.0f, 0.0f, DECO_HIDE_ROT);
                _decoImage.enabled = true;
                posX = DECO_SHOW_POS_X;
                rot = DECO_SHOW_ROT;
            }
            else
            {
                if (!isEnabled && _decoballSequence != null)
                    return;

                _decoImage.transform.localPosition = new Vector3(DECO_SHOW_POS_X, DECO_POS_Y, 0.0f);
                _decoImage.transform.rotation = Quaternion.Euler(0.0f, 0.0f, DECO_SHOW_ROT);
                callback = () => _decoImage.enabled = false;
                posX = DECO_HIDE_POS_X;
                rot = DECO_HIDE_ROT;
            }

            var moveTween = DG.Tweening.TweenSettingsExtensions.SetEase(DG.Tweening.ShortcutExtensions.DOLocalMoveX(_decoImage.rectTransform, posX, 0.25f, false), DG.Tweening.Ease.OutSine);
            var rotTween = DG.Tweening.TweenSettingsExtensions.SetEase(DG.Tweening.ShortcutExtensions.DORotate(_decoImage.transform, new Vector3(0.0f, 0.0f, rot), 0.25f, DG.Tweening.RotateMode.FastBeyond360), DG.Tweening.Ease.Linear);
            if (_decoballSequence != null)
                DG.Tweening.TweenExtensions.Kill(_decoballSequence, false);

            var sequence = DG.Tweening.TweenSettingsExtensions.Join(DG.Tweening.TweenSettingsExtensions.Join(DG.Tweening.DOTween.Sequence(), moveTween), rotTween);
            sequence = DG.Tweening.TweenSettingsExtensions.SetDelay(sequence, 0.125f);
            sequence = DG.Tweening.TweenSettingsExtensions.OnComplete(sequence, () =>
            {
                callback?.Invoke();
                _decoballSequence = null;
            });
            _decoballSequence = DG.Tweening.TweenExtensions.Play(DG.Tweening.TweenSettingsExtensions.SetLink(sequence, gameObject));
        }
		private bool IsNearSide(global::Dpr.Battle.Logic.BtlPokePos pos) {
