		private void OnSwapPokemon(global::System.Collections.Generic.List<global::Dpr.Battle.Logic.BTL_POKEPARAM> pokemonParams, global::Dpr.UI.PokemonBattleWindow.PositionType posType) {
            var viewSystem = BattleViewCore.Instance.ViewSystem;
            if (pokemonParams.Count == 2)
            {
                for (byte i = 0; i < pokemonParams.Count; i++)
                {
                    var bpp = pokemonParams[i];
                    if (bpp == null)
                        continue;

                    byte selIdx = _pokeSelParam.GetParty().GetMemberIndex(bpp.GetID());
                    var outPoke = viewSystem.GetBattlePokeParam(i != 0 ? BtlvPos.BTL_VPOS_NEAR_2 : BtlvPos.BTL_VPOS_NEAR_1);
                    _pokeSelResult.Push(_pokeSelParam.GetParty().GetMemberIndex(outPoke.GetID()), selIdx);
                }
            }
            else
            {
                for (byte i = 0; i < pokemonParams.Count; i++)
                {
                    var bpp = pokemonParams[i];
                    if (bpp == null)
                        continue;

                    byte selIdx = _pokeSelParam.GetParty().GetMemberIndex(bpp.GetID());
                    if (_actionParam.pokeIndex == 0)
                        _swapWaitPokemon = bpp;

                    _pokeSelResult.Push((byte)_outMemberIndex, selIdx);
                }
            }

            _actionList.ResetSelect();
            _wazaList.ResetSelect();
        }
