		private global::Dpr.UI.PokemonBattleWindow.Param.BattleType GetBattleType() {
            var viewSystem = BattleViewCore.Instance.ViewSystem;
            PokemonBattleWindow.Param.BattleType type;
            switch (viewSystem.GetMainModule().GetMultiMode())
            {
                case BtlMultiMode.BTL_MULTIMODE_NONE:
                    switch (viewSystem.GetBattleRule())
                    {
                        case BtlRule.BTL_RULE_DOUBLE:
                            type = PokemonBattleWindow.Param.BattleType.Double;
                            break;
                        case BtlRule.BTL_RULE_SAFARI:
                            type = PokemonBattleWindow.Param.BattleType.Safari;
                            break;
                        default:
                            type = PokemonBattleWindow.Param.BattleType.Normal;
                            break;
                    }
                    break;
                case BtlMultiMode.BTL_MULTIMODE_PP_PP:
                case BtlMultiMode.BTL_MULTIMODE_PP_AA:
                    type = PokemonBattleWindow.Param.BattleType.MultiPlayer;
                    break;
                case BtlMultiMode.BTL_MULTIMODE_P_AA:
                    type = PokemonBattleWindow.Param.BattleType.Double;
                    break;
                default:
                    type = PokemonBattleWindow.Param.BattleType.Normal;
                    break;
            }

            if (viewSystem.GetMainModule().IsScenarioMultiBattle())
                type = PokemonBattleWindow.Param.BattleType.Normal;

            return type;
        }
		private bool IsOpenMessage() {
            if (MsgWindow.MsgWindowManager.Instance == null)
                return false;

            if (MsgWindow.MsgWindowManager.Instance.MsgWindow == null)
                return false;

            return MsgWindow.MsgWindowManager.Instance.MsgWindow.IsOpen;
        }
		private bool IsEndMessage() {
            if (MsgWindow.MsgWindowManager.Instance == null || MsgWindow.MsgWindowManager.Instance.MsgWindow == null)
                return true;

            if (MsgWindow.MsgWindowManager.Instance.MsgWindow.IsOpen)
                return false;

            return _messagePramQueue.Count <= 0;
        }
		private void SetMessageQueue(global::Dpr.Message.MessageTextParseDataModel strBuf, global::Dpr.Battle.View.Systems.MsgShowParam showParam) {
            _messagePramQueue.Enqueue((strBuf, showParam));
            if (_coMsgQueue == null)
            {
                _isMsgEnd = false;
                _coMsgQueue = StartCoroutine(MessageWindowCoroutine());
            }
        }
		private global::System.Collections.IEnumerator MessageWindowCoroutine() {
            if (_actionList.IsShow)
                _actionList.Hide(false, null);

            if (_actionList.animationState == BattleViewUICanvasBase.BattleUIAnimationState.Opened)
                ShowActionListOnly(false);

            if (IsOpenedStatus())
                SwitchShowStatusWindows(false);

            yield return null;

            while (IsOpenMessage() || _messagePramQueue.Count > 0)
            {
                if (IsOpenMessage())
                {
                    if (MsgWindow.MsgWindowManager.Instance.MsgWindow.MsgState == MsgWindow.MsgWindowDataModel.MsgWindowState.Keywait)
                    {
                        if (!_showParam.IsKeyWait)
                        {
                            yield return new WaitForSeconds(0.4f);
                            MsgWindow.MsgWindowManager.Instance.MsgWindow.MoveNextPage();
                        }

                        yield return new WaitUntil(() => MsgWindow.MsgWindowManager.Instance.MsgWindow.MsgState != MsgWindow.MsgWindowDataModel.MsgWindowState.Keywait);
                    }
                    else if (MsgWindow.MsgWindowManager.Instance.MsgWindow.MsgState == MsgWindow.MsgWindowDataModel.MsgWindowState.FinishedShowMessage)
                    {
                        if (!_isMsgEnd)
                        {
                            _isMsgEnd = true;
                            _msgTimer = _msgTimeOut;
                        }
                        else
                        {
                            _msgTimer -= Time.deltaTime;
                        }

                        if (_endMsgAction != null)
                        {
                            _endMsgAction();
                            _endMsgAction = null;
                        }

                        if (_isMessageSleep)
                        {
                            if (_msgTimer <= 0.0f)
                            {
                                global::UnityEngine.Debug.LogWarning("<color=yellow> Time Out ! </color>");
                                _isMessageSleep = false;
                            }
                        }
                        else if (_showParam.IsKeyWait)
                        {
                            if (!NetworkUtils.NetworkManager.IsShowApplicationErrorDialog() &&
                                (BtlvInput.GetPush(UIManager.ButtonA, true) || BtlvInput.GetPush(UIManager.ButtonB, true)))
                            {
                                CloseMessageWindow();
                            }
                        }
                        else if (_showParam.MsgAfterglow != 0xff)
                        {
                            if (_showParam.MsgAfterglow > 0)
#if PC_UNLOCKED_FPS
                                _showParam.MsgAfterglow = Mathf.Max(0, _showParam.MsgAfterglow - PcPlatform.PcFrameClock.Ticks);
#else
                                _showParam.MsgAfterglow--;
#endif
#if PC_UNLOCKED_FPS
                            else if (PcPlatform.PcFrameClock.Ticks > 0 && UIManager.Instance.GetCurrentUIWindow<ContextMenuWindow>() == null)
#else
                            else if (UIManager.Instance.GetCurrentUIWindow<ContextMenuWindow>() == null)
#endif
                                CloseMessageWindow();
                        }
                    }
                }
                else
                {
                    bool isWaitStatus = false;
                    for (int i = 0; i < _statusWindows.Length; i++)
                    {
                        var window = _statusWindows[i];
                        if (window != null && (window.IsTransition || window.IsHpBarPlaying))
                        {
                            isWaitStatus = true;
                            break;
                        }
                    }

                    if (!isWaitStatus && _messagePramQueue.Count > 0)
                    {
                        var item = _messagePramQueue.Dequeue();
                        OpenMessageWindow(item.Item1, item.Item2);
                        _isMsgEnd = false;
                    }
                }

                yield return null;
            }

            _coMsgQueue = null;
        }
		private void OpenMessageWindow(global::Dpr.Message.MessageTextParseDataModel strBuf, global::Dpr.Battle.View.Systems.MsgShowParam showParam) {
            _showParam = showParam;
            var msgWindowParam = BtlvUtility.MakeMsgWindowParam(strBuf);
            msgWindowParam.inputEnabled = true;
            _msgWindow = MsgWindow.MsgWindowManager.OpenBtlMsg(msgWindowParam);
        }
		private void CloseMessageWindow() {
            if (IsOpenMessage())
                MsgWindow.MsgWindowManager.CloseMsg();

            _isMessageSleep = false;
            _showParam = MsgShowParam.Default;
        }
		private void OpenSelectWindow(bool bCancel, global::Dpr.Battle.Logic.YesNoMode mode) {
            // bCancel is never read here (useCancel is always true)
            if (mode == YesNoMode.YESNO_MODE_YESNO)
            {
                MsgWindow.MsgWindowManager.OpenYesNoMenu(index =>
                {
                    _yesnoResult = index != 0 ? BtlYesNo.BTL_YESNO_NO : BtlYesNo.BTL_YESNO_YES;
                }, ContextMenuWindow.CursorType.Arrow, true, false, null, AK.EVENTS.UI_COMMON_DECIDE);
            }
            else
            {
                MsgWindow.MsgWindowManager.OpenCustomMenu(ContextMenuMsgFile, ContextMenuText[(int)mode - 1], index =>
                {
                    _yesnoResult = index != 0 ? BtlYesNo.BTL_YESNO_NO : BtlYesNo.BTL_YESNO_YES;
                }, ContextMenuWindow.CursorType.Arrow, true, 0, null, AK.EVENTS.UI_COMMON_DECIDE);
            }
        }
		private void OpenMenuUI<T>(global::UIWindowID id, global::System.Action<T> openProc, bool doDuckoff = true) where T : global::Dpr.UI.UIWindow {
            T window = UIManager.Instance.CreateUIWindow<T>(id);
            _uiWindow = window;
            _isMenuUIEnd = false;
            window.onClosed = _ =>
            {
                _isMenuUIEnd = true;
                if (doDuckoff)
                    Audio.AudioManager.Instance.SetBgmEvent(AK.EVENTS.DUCKOFF_BGM, false);
            };

            if (openProc != null)
                openProc(window);

            if (doDuckoff)
                Audio.AudioManager.Instance.SetBgmEvent(AK.EVENTS.DUCKON_BGM, false);
        }
		private void ForceQuitMenuUI<T>(global::System.Action<T> closeProc, bool isMenuShow = true) where T : global::Dpr.UI.UIWindow {
            _coCloseMenuUI = StartCoroutine(CloseMenuUICoroutine(closeProc, isMenuShow));
        }
		private global::System.Collections.IEnumerator CloseMenuUICoroutine<T>(global::System.Action<T> closeProc, bool isMenuShow = true) where T : global::Dpr.UI.UIWindow {
            UIWindow result = null;
            while (result == null)
            {
                if (_uiWindow is T)
                {
                    for (int i = UIManager.Instance.GetUIWindowCount() - 1; i >= 0; i--)
                    {
                        var window = UIManager.Instance.GetUIWindowByIndex(i);
                        if (window != null)
                        {
                            if (window.IsClosing)
                                break;

                            if (window is T t)
                            {
                                t.onClosed += _ =>
                                {
                                    UIManager.Instance.FadeoutBlurBg(0.5f, null);
                                    if (isMenuShow)
                                        Show(false);
                                };
                                if (closeProc != null)
                                    closeProc(t);

                                result = t;
                            }
                            else if (window is PokemonStatusWindow)
                            {
                                var statusWindow = window as PokemonStatusWindow;
                                statusWindow.Close(w => statusWindow.onClosed.Invoke(w), UIWindowID.POKEMON_BATTLE);
                            }
                            else if (window is ContextMenuWindow)
                            {
                                (window as ContextMenuWindow).Close(null);
                            }
                        }
                    }
                }

                yield return null;
            }

            _coCloseMenuUI = null;
        }
