		public string GetAffinityText(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, global::Pml.WazaNo wazaNo, global::Dpr.Battle.Logic.BTL_POKEPARAM target) {
            var targets = new List<BTL_POKEPARAM>();
