		public string GetAffinityText(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, global::Pml.WazaNo wazaNo, global::System.Collections.Generic.List<global::Dpr.Battle.Logic.BTL_POKEPARAM> targets) {
            if (bpp == null || targets == null || targets.Count == 0)
