		public global::UnityEngine.Sprite GetAffinitySprite(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, global::Pml.WazaNo wazaNo, global::Dpr.Battle.Logic.BTL_POKEPARAM target) {
