		public global::UnityEngine.Sprite GetAffinitySprite(global::Dpr.Battle.Logic.BTL_POKEPARAM bpp, global::Pml.WazaNo wazaNo, global::System.Collections.Generic.List<global::Dpr.Battle.Logic.BTL_POKEPARAM> targets) {
            if (bpp == null || targets == null || targets.Count == 0)
                return null;

            string spriteName = BattleAffinityInfo.CheckWazaAffinity(bpp, wazaNo, targets, out var affinity) ? AffinitySpriteName[(int)affinity] : "";
            if (spriteName == "")
                return null;

            return UIManager.Instance.GetAtlasSprite(SpriteAtlasID.BATTLE_LANG, spriteName);
        }
		public void PlaySe(uint eventId) {
